class Token<T> {
  declare readonly __type: T;
  constructor(readonly name: string) {}
}

class Container {
  readonly #factories = new Map<Token<unknown>, () => unknown>();
  readonly #instances = new Map<Token<unknown>, unknown>();

  register<T>(token: Token<T>, factory: () => T): void {
    this.#factories.set(token, factory);
  }

  resolve<T>(token: Token<T>): T {
    if (this.#instances.has(token)) return this.#instances.get(token) as T;
    const factory = this.#factories.get(token);
    if (factory === undefined) throw new Error(`nothing registered for ${token.name}`);
    const instance = factory() as T;
    this.#instances.set(token, instance);
    return instance;
  }
}

const POOL = new Token<{ size: number }>("Pool");
const MAILER = new Token<{ send(to: string): void }>("Mailer");
const container = new Container();
container.register(POOL, () => ({ size: 10 }));
console.log("same:", container.resolve(POOL) === container.resolve(POOL));
try {
  container.resolve(MAILER);
} catch (error) {
  console.log((error as Error).message);
}

