type Level = "info" | "warn";
const RANK: Record<Level, number> = { info: 1, warn: 2 };

interface Logger {
  info(message: string, extra?: Record<string, unknown>): void;
  warn(message: string, extra?: Record<string, unknown>): void;
  child(extra: Record<string, unknown>): Logger;
}

function createLogger(level: Level, fields: Record<string, unknown> = {}): Logger {
  const write = (entryLevel: Level) => (message: string, extra: Record<string, unknown> = {}) => {
    if (RANK[entryLevel] < RANK[level]) return;
    console.log(JSON.stringify({ level: entryLevel, message, ...fields, ...extra }));
  };
  return { info: write("info"), warn: write("warn"), child: (extra) => createLogger(level, { ...fields, ...extra }) };
}

const root = createLogger("warn", { service: "bookstore" });
root.info("not shown");
const request = root.child({ requestId: "req-7" });
request.warn("slow query", { ms: 840 });
request.info("also not shown");
createLogger("info").info("started");

