class Cart {
  items: string[] = [];
  dispose(): void {
    console.log(`released cart with ${this.items.length} items`);
  }
}

function createScope() {
  let cart: Cart | undefined;
  return {
    resolveCart(): Cart {
      cart ??= new Cart();
      return cart;
    },
    async dispose(): Promise<void> {
      cart?.dispose();
      cart = undefined;
    },
  };
}

const ada = createScope();
ada.resolveCart().items.push("RICE-50KG");
ada.resolveCart().items.push("OIL-5L");
const tunde = createScope();
console.log("separate carts:", ada.resolveCart() !== tunde.resolveCart());
await ada.dispose();
await createScope().dispose();
