const deps: Record<string, string[]> = {
  http: ["catalog", "orders"],
  catalog: ["database", "cache"],
  orders: ["database"],
  database: [],
  cache: [],
};

function levels(graph: Record<string, string[]>): string[][] {
  const level = new Map<string, number>();
  const levelOf = (name: string): number => {
    const known = level.get(name);
    if (known !== undefined) return known;
    const parents = graph[name] ?? [];
    const value = parents.length === 0 ? 0 : Math.max(...parents.map(levelOf)) + 1;
    level.set(name, value);
    return value;
  };
  const groups: string[][] = [];
  for (const name of Object.keys(graph).sort((a, b) => levelOf(a) - levelOf(b))) {
    (groups[levelOf(name)] ??= []).push(name);
  }
  return groups;
}

console.log(levels(deps));

